G['pipes-and-cisterns'] = {
  easy: [
    (r) => { const [a, b] = pick(r, workPairs); return { q: `Two pipes can fill a tank in ${a} hours and ${b} hours respectively. If both are opened together, how long will it take to fill the tank?`, a: `${fmtNum((a * b) / (a + b))} hours`, d: [`${(a + b) / 2} hours`, `${fmtNum((a * b) / (a + b) + 1)} hours`, `${b - a} hours`, `${fmtNum(round2((a * b) / (a + b) * 1.5))} hours`], e: `Time = ab/(a + b) = ${fmtNum((a * b) / (a + b))} hours.` }; },
  ],
  medium: [
    (r) => { const [a, b] = pick(r, workPairs); return { q: `A pipe fills a tank in ${a} hours and a leak empties the full tank in ${b} hours. With both working, how long does it take to fill the tank?`, a: `${fmtNum(round2((a * b) / (b - a)))} hours`, d: [`${fmtNum((a * b) / (a + b))} hours`, `${b - a} hours`, `${fmtNum(round2((a * b) / (b - a) + 2))} hours`, `${a + b} hours`], e: `Net rate = 1/${a} - 1/${b}. Time = ab/(b - a) = ${fmtNum(round2((a * b) / (b - a)))} hours.` }; },
    (r) => { const [a, b] = pick(r, workPairs); const t = pick(r, [1, 2, 3]); if (t >= a) return null; const rem = 1 - t / a; const x = round2(rem * b); return { q: `Pipe A fills a tank in ${a} hours. After ${t} hour(s), A is closed and pipe B, which alone fills it in ${b} hours, is opened. How long will B take to fill the rest?`, a: `${fmtNum(x)} hours`, d: [`${b - t} hours`, `${fmtNum(round2(x + 1))} hours`, `${fmtNum(round2(rem * a))} hours`, `${fmtNum(round2(x / 2))} hours`], e: `A fills ${t}/${a}. Remaining ${fmtNum(round2(rem))} is filled by B in ${fmtNum(round2(rem))} × ${b} = ${fmtNum(x)} hours.` }; },
  ],
  hard: [
    (r) => { const sets = [[10, 12, 20], [6, 8, 12], [12, 15, 20], [10, 15, 12], [5, 10, 6], [8, 12, 16]]; const [a, b, c] = pick(r, sets); const rate = 1 / a + 1 / b - 1 / c; if (rate <= 0) return null; const t = round2(1 / rate); return { q: `Pipes A and B can fill a tank in ${a} and ${b} hours, while pipe C can empty it in ${c} hours. If all three are opened together, in how many hours will the tank be filled?`, a: `${fmtNum(t)} hours`, d: [`${fmtNum(round2(1 / (1 / a + 1 / b + 1 / c)))} hours`, `${fmtNum(round2(t + 2))} hours`, `${fmtNum(round2(t / 2))} hours`, `${a + b - c} hours`], e: `Net rate = 1/${a} + 1/${b} - 1/${c} = ${round2(rate)} per hour, so time = ${fmtNum(t)} hours.` }; },
    (r) => { const a = pick(r, [12, 15, 20, 24, 30]); const k = pick(r, [2, 3]); const b = a / k; return { q: `One pipe can fill a tank ${k} times as fast as another. Together they fill it in ${fmtNum((a * b) / (a + b))} hours. How long would the slower pipe alone take?`, a: `${a} hours`, d: [`${fmtNum(b)} hours`, `${a + k} hours`, `${a * 2} hours`, `${fmtNum((a + b) / 2)} hours`], e: `If the slower takes x hours, the faster takes x/${k}. Together: 1/x + ${k}/x = ${k + 1}/x = 1/${fmtNum((a * b) / (a + b))} → x = ${a}.` }; },
  ],
};

G['time-speed-distance'] = {
  easy: [
    (r) => { const v = pick(r, [18, 36, 54, 72, 90, 108, 126, 144]); return { q: `Convert ${v} km/h into m/s.`, a: `${(v * 5) / 18} m/s`, d: [`${v / 3} m/s`, `${(v * 18) / 5} m/s`, `${(v * 5) / 18 + 5} m/s`, `${v / 2} m/s`], e: `Multiply by 5/18: ${v} × 5/18 = ${(v * 5) / 18} m/s.` }; },
    (r) => { const s = int(r, 20, 90), t = int(r, 2, 8); return { q: `A car travels at ${s} km/h for ${t} hours. How far does it travel?`, a: `${s * t} km`, d: [`${s * t + s} km`, `${s + t} km`, `${s * (t - 1)} km`, `${s * t * 2} km`], e: `Distance = speed × time = ${s} × ${t} = ${s * t} km.` }; },
    (r) => { const d = int(r, 10, 60) * 10, t = pick(r, [2, 4, 5, 8, 10]); if (d % t) return null; return { q: `A cyclist covers ${d} km in ${t} hours. What is his speed?`, a: `${d / t} km/h`, d: [`${d / t + 5} km/h`, `${d * t} km/h`, `${d / t - 4} km/h`, `${d / 2} km/h`], e: `Speed = distance/time = ${d}/${t} = ${d / t} km/h.` }; },
  ],
  medium: [
    (r) => { const x = int(r, 20, 60), y = int(r, 30, 80); if (x === y) return null; const av = round2((2 * x * y) / (x + y)); return { q: `A person goes to a place at ${x} km/h and returns at ${y} km/h. What is the average speed for the whole journey?`, a: `${fmtNum(av)} km/h`, d: [`${(x + y) / 2} km/h`, `${fmtNum(round2(av + 2))} km/h`, `${fmtNum(round2(av - 3))} km/h`, `${Math.max(x, y)} km/h`], e: `Equal distances → average speed = 2xy/(x + y) = 2×${x}×${y}/${x + y} = ${fmtNum(av)} km/h.` }; },
    (r) => { const D = int(r, 10, 40) * 10, a = int(r, 20, 60), b = int(r, 20, 60); const t = round2(D / (a + b)); return { q: `Two cars start at the same time from towns ${D} km apart and move towards each other at ${a} km/h and ${b} km/h. After how many hours will they meet?`, a: `${fmtNum(t)} hours`, d: [`${fmtNum(round2(D / Math.abs(a - b || 1)))} hours`, `${fmtNum(round2(t + 1))} hours`, `${fmtNum(round2(t / 2))} hours`, `${fmtNum(round2(D / a))} hours`], e: `Relative speed = ${a} + ${b} = ${a + b} km/h. Time = ${D}/${a + b} = ${fmtNum(t)} h.` }; },
    (r) => { const s = pick(r, [30, 40, 45, 50, 60]); const k = pick(r, [3, 4, 5]); const late = pick(r, [10, 12, 15, 20]); const t = (late / 60) * (k / 1) ; const dist = round2(s * t * (k - 1) / (k - 1)); void dist; const realT = (late / 60) * k / 1; return { q: `Walking at ${k - 1}/${k} of his usual speed, a man is ${late} minutes late. What is his usual time to cover the distance?`, a: `${fmtNum(round2((k - 1) * late))} minutes`, d: [`${late * k} minutes`, `${fmtNum(round2((k - 1) * late + 10))} minutes`, `${late} minutes`, `${fmtNum(round2(late * k / 2))} minutes`], e: `At ${k - 1}/${k} speed, time becomes ${k}/${k - 1} of usual. Extra = usual/${k - 1} = ${late} min → usual = ${(k - 1) * late} min.` }; },
  ],
  hard: [
    (r) => { const D = int(r, 6, 30) * 10, v1 = pick(r, [40, 50, 60]), dv = pick(r, [10, 20]); const t1 = D / v1, t2 = D / (v1 + dv); const diff = round2((t1 - t2) * 60); if (!Number.isInteger(diff)) return null; return { q: `A train covers ${D} km at a uniform speed. If its speed were ${dv} km/h more, it would take ${diff} minutes less. What is its usual speed?`, a: `${v1} km/h`, d: [`${v1 + dv} km/h`, `${v1 - 10} km/h`, `${v1 + 5} km/h`, `${fmtNum(D / 3)} km/h`], e: `${D}/v - ${D}/(v + ${dv}) = ${diff}/60 hours. Solving gives v = ${v1} km/h (check: ${fmtNum(t1)} h vs ${fmtNum(round2(t2))} h).` }; },
    (r) => { const a = pick(r, [4, 5, 6]), b = a + pick(r, [1, 2, 3]), gap = pick(r, [1, 2]); const head = a * gap; const t = head / (b - a); return { q: `A thief runs at ${a} km/h. A policeman starts chasing him ${gap} hour(s) later at ${b} km/h. After how many hours from the policeman's start will he catch the thief?`, a: `${fmtNum(t)} hours`, d: [`${fmtNum(t + gap)} hours`, `${fmtNum(round2(head / (a + b)))} hours`, `${fmtNum(t * 2)} hours`, `${b - a} hours`], e: `Head start = ${a}×${gap} = ${head} km. Relative speed = ${b - a} km/h. Time = ${head}/${b - a} = ${fmtNum(t)} hours.` }; },
  ],
};

G['trains'] = {
  easy: [
    (r) => { const v = pick(r, [36, 54, 72, 90, 108]), L = int(r, 10, 40) * 10; const t = round2(L / ((v * 5) / 18)); return { q: `A train ${L} m long runs at ${v} km/h. How long does it take to cross a pole?`, a: `${fmtNum(t)} seconds`, d: [`${fmtNum(round2(t + 4))} seconds`, `${fmtNum(round2(L / v))} seconds`, `${fmtNum(round2(t * 2))} seconds`, `${fmtNum(round2(t - 2))} seconds`], e: `Speed = ${v} × 5/18 = ${(v * 5) / 18} m/s. Time = ${L}/${(v * 5) / 18} = ${fmtNum(t)} s.` }; },
    (r) => { const t = int(r, 6, 20), sp = pick(r, [10, 15, 20, 25]); return { q: `A train crosses a pole in ${t} seconds at ${sp} m/s. What is its length?`, a: `${t * sp} m`, d: [`${t * sp + 20} m`, `${t + sp} m`, `${t * sp - 30} m`, `${t * sp * 2} m`], e: `Length = speed × time = ${sp} × ${t} = ${t * sp} m.` }; },
  ],
  medium: [
    (r) => { const v = pick(r, [36, 54, 72, 90]), L = int(r, 10, 30) * 10, P = int(r, 10, 40) * 10; const t = round2((L + P) / ((v * 5) / 18)); return { q: `A train ${L} m long running at ${v} km/h crosses a platform ${P} m long. How long does it take?`, a: `${fmtNum(t)} seconds`, d: [`${fmtNum(round2(L / ((v * 5) / 18)))} seconds`, `${fmtNum(round2(t + 5))} seconds`, `${fmtNum(round2(P / ((v * 5) / 18)))} seconds`, `${fmtNum(round2(t * 1.5))} seconds`], e: `Distance = ${L} + ${P} = ${L + P} m. Speed = ${(v * 5) / 18} m/s. Time = ${fmtNum(t)} s.` }; },
    (r) => { const sp = pick(r, [10, 15, 20]), tp = int(r, 8, 15), tpl = tp + int(r, 5, 15); const L = sp * tp, P = sp * (tpl - tp); return { q: `A train crosses a pole in ${tp} s and a ${P} m platform in ${tpl} s. Find the length of the train.`, a: `${L} m`, d: [`${P} m`, `${L + P} m`, `${L + 25} m`, `${Math.abs(L - 30)} m`], e: `Platform takes ${tpl - tp} s extra → speed = ${P}/${tpl - tp} = ${sp} m/s. Length = ${sp} × ${tp} = ${L} m.` }; },
  ],
  hard: [
    (r) => { const v1 = pick(r, [36, 54, 72]), v2 = pick(r, [18, 36, 54]), L1 = int(r, 10, 25) * 10, L2 = int(r, 10, 25) * 10; const t = round2((L1 + L2) / (((v1 + v2) * 5) / 18)); return { q: `Two trains of lengths ${L1} m and ${L2} m run on parallel tracks in opposite directions at ${v1} km/h and ${v2} km/h. How long will they take to cross each other?`, a: `${fmtNum(t)} seconds`, d: [`${fmtNum(round2((L1 + L2) / ((Math.abs(v1 - v2) || 18) * 5 / 18)))} seconds`, `${fmtNum(round2(t + 3))} seconds`, `${fmtNum(round2(t * 2))} seconds`, `${fmtNum(round2(t - 2))} seconds`], e: `Opposite directions: relative speed = ${v1 + v2} km/h = ${fmtNum(round2(((v1 + v2) * 5) / 18))} m/s. Time = (${L1} + ${L2})/${fmtNum(round2(((v1 + v2) * 5) / 18))} = ${fmtNum(t)} s.` }; },
    (r) => { const v1 = pick(r, [72, 90, 108]), v2 = pick(r, [36, 54]), L1 = int(r, 10, 25) * 10, L2 = int(r, 10, 25) * 10; const t = round2((L1 + L2) / (((v1 - v2) * 5) / 18)); return { q: `A ${L1} m train at ${v1} km/h overtakes a ${L2} m train moving in the same direction at ${v2} km/h. How long does overtaking take?`, a: `${fmtNum(t)} seconds`, d: [`${fmtNum(round2((L1 + L2) / (((v1 + v2) * 5) / 18)))} seconds`, `${fmtNum(round2(t + 6))} seconds`, `${fmtNum(round2(t / 2))} seconds`, `${fmtNum(round2(L1 / (((v1 - v2) * 5) / 18)))} seconds`], e: `Same direction: relative speed = ${v1 - v2} km/h = ${fmtNum(round2(((v1 - v2) * 5) / 18))} m/s. Time = ${L1 + L2}/${fmtNum(round2(((v1 - v2) * 5) / 18))} = ${fmtNum(t)} s.` }; },
  ],
};

G['boats-and-streams'] = {
  easy: [
    (r) => { const b = int(r, 8, 30), s = int(r, 1, 6); return { q: `A boat's speed in still water is ${b} km/h and the stream flows at ${s} km/h. What is the downstream speed?`, a: `${b + s} km/h`, d: [`${b - s} km/h`, `${b} km/h`, `${b + 2 * s} km/h`, `${(b + s) / 2} km/h`], e: `Downstream = boat + stream = ${b + s} km/h.` }; },
    (r) => { const b = int(r, 8, 30), s = int(r, 1, 6); return { q: `A boat's speed in still water is ${b} km/h and the stream flows at ${s} km/h. What is the upstream speed?`, a: `${b - s} km/h`, d: [`${b + s} km/h`, `${b} km/h`, `${b - 2 * s} km/h`, `${s} km/h`], e: `Upstream = boat - stream = ${b - s} km/h.` }; },
  ],
  medium: [
    (r) => { const b = int(r, 6, 25), s = int(r, 1, 5); return { q: `A man rows downstream at ${b + s} km/h and upstream at ${b - s} km/h. What is his speed in still water?`, a: `${b} km/h`, d: [`${s} km/h`, `${b + s} km/h`, `${b + 1} km/h`, `${2 * b} km/h`], e: `Still water speed = (down + up)/2 = (${b + s} + ${b - s})/2 = ${b} km/h.` }; },
    (r) => { const b = int(r, 6, 25), s = int(r, 1, 5); return { q: `A boat goes downstream at ${b + s} km/h and upstream at ${b - s} km/h. What is the speed of the stream?`, a: `${s} km/h`, d: [`${b} km/h`, `${2 * s} km/h`, `${s + 1} km/h`, `${b - s} km/h`], e: `Stream speed = (down - up)/2 = ${2 * s}/2 = ${s} km/h.` }; },
  ],
  hard: [
    (r) => { const b = int(r, 8, 20), s = int(r, 2, 4), D = (b * b - s * s) * int(r, 1, 2) / 2; if (!Number.isInteger(D)) return null; const T = round2(D / (b + s) + D / (b - s)); return { q: `A boat with speed ${b} km/h in still water goes ${D} km downstream and comes back. The stream flows at ${s} km/h. What is the total time taken?`, a: `${fmtNum(T)} hours`, d: [`${fmtNum(round2((2 * D) / b))} hours`, `${fmtNum(round2(T + 1))} hours`, `${fmtNum(round2(T - 1))} hours`, `${fmtNum(round2(D / b))} hours`], e: `Time = ${D}/${b + s} + ${D}/${b - s} = ${fmtNum(round2(D / (b + s)))} + ${fmtNum(round2(D / (b - s)))} = ${fmtNum(T)} h.` }; },
    (r) => { const s = int(r, 1, 4), k = pick(r, [2, 3]); const b = s * (k + 1) / (k - 1); if (!Number.isInteger(b)) return null; return { q: `A man takes ${k} times as long to row upstream as to row the same distance downstream. If the stream flows at ${s} km/h, find his speed in still water.`, a: `${b} km/h`, d: [`${b + s} km/h`, `${s * k} km/h`, `${b - 1} km/h`, `${b * 2} km/h`], e: `(b + s)/(b - s) = ${k} → b = s(k + 1)/(k - 1) = ${s}×${k + 1}/${k - 1} = ${b} km/h.` }; },
  ],
};

G['probability'] = {
  easy: [
    (r) => { const ev = pick(r, [['an even number', 3], ['a number greater than 4', 2], ['a prime number', 3], ['a multiple of 3', 2], ['a number less than 3', 2], ['the number 6', 1]]); return { q: `A fair die is rolled once. What is the probability of getting ${ev[0]}?`, a: frac(ev[1], 6), d: [frac(ev[1] + 1, 6), frac(Math.max(1, ev[1] - 1), 6), '1/2', '1/3', '2/3', '1/6'], e: `Favourable outcomes = ${ev[1]} out of 6. Probability = ${frac(ev[1], 6)}.` }; },
    (r) => { const n = pick(r, [2, 3]); const ev = n === 2 ? pick(r, [['exactly one head', 2], ['at least one head', 3], ['two heads', 1]]) : pick(r, [['exactly two heads', 3], ['at least one tail', 7], ['all heads', 1], ['exactly one head', 3]]); const tot = 2 ** n; return { q: `${n} fair coins are tossed. What is the probability of getting ${ev[0]}?`, a: frac(ev[1], tot), d: [frac(ev[1] + 1, tot), frac(Math.max(1, ev[1] - 1), tot), '1/2', '3/4', '1/8'], e: `Total outcomes = ${tot}; favourable = ${ev[1]}. Probability = ${frac(ev[1], tot)}.` }; },
    (r) => { const red = int(r, 2, 9), blue = int(r, 2, 9), green = int(r, 1, 6); const c = pick(r, [['red', red], ['blue', blue], ['green', green]]); const t = red + blue + green; return { q: `A bag has ${red} red, ${blue} blue and ${green} green balls. One ball is drawn at random. What is the probability it is ${c[0]}?`, a: frac(c[1], t), d: [frac(t - c[1], t), frac(c[1], t - c[1]), frac(1, 3), frac(c[1] + 1, t)], e: `P = ${c[1]}/${t} = ${frac(c[1], t)}.` }; },
  ],
  medium: [
    (r) => { const s = int(r, 2, 12); const ways = [1, 2, 3, 4, 5, 6, 5, 4, 3, 2, 1][s - 2]; return { q: `Two dice are thrown together. What is the probability that the sum is ${s}?`, a: frac(ways, 36), d: [frac(ways + 1, 36), frac(Math.max(1, ways - 1), 36), frac(1, 6), frac(1, 12), frac(s, 36)], e: `There are ${ways} favourable pairs out of 36. P = ${frac(ways, 36)}.` }; },
    (r) => { const ev = pick(r, [['a king', 4], ['a heart', 13], ['a red card', 26], ['a face card', 12], ['a red king', 2], ['an ace or a king', 8], ['a black face card', 6]]); return { q: `One card is drawn from a well-shuffled deck of 52 cards. What is the probability of drawing ${ev[0]}?`, a: frac(ev[1], 52), d: [frac(ev[1] + 2, 52), frac(Math.max(1, ev[1] - 1), 52), '1/4', '1/13', '1/2', '3/13'], e: `Favourable cards = ${ev[1]}. P = ${ev[1]}/52 = ${frac(ev[1], 52)}.` }; },
    (r) => { const n = pick(r, [20, 25, 30, 40, 50]), k = pick(r, [3, 4, 5, 7]); const c = Math.floor(n / k); return { q: `A number is picked at random from 1 to ${n}. What is the probability it is a multiple of ${k}?`, a: frac(c, n), d: [frac(c + 1, n), frac(1, k + 1), frac(Math.max(1, c - 1), n), frac(k, n)], e: `Multiples of ${k} up to ${n}: ${c}. P = ${c}/${n} = ${frac(c, n)}.` }; },
  ],
  hard: [
    (r) => { const R2 = int(r, 3, 7), B = int(r, 3, 7); const t = R2 + B; const num = nCr(R2, 2) + nCr(B, 2), den = nCr(t, 2); return { q: `A bag has ${R2} red and ${B} black balls. Two balls are drawn at random without replacement. What is the probability that both are the same colour?`, a: frac(num, den), d: [frac(den - num, den), frac(nCr(R2, 2), den), '1/2', frac(num + 1, den)], e: `P = [C(${R2},2) + C(${B},2)]/C(${t},2) = (${nCr(R2, 2)} + ${nCr(B, 2)})/${den} = ${frac(num, den)}.` }; },
    (r) => { const pa = pick(r, [[1, 2], [1, 3], [2, 3], [1, 4], [3, 4], [2, 5]]), pb = pick(r, [[1, 2], [1, 3], [2, 3], [1, 4], [3, 5]]); const num = pa[1] * pb[1] - (pa[1] - pa[0]) * (pb[1] - pb[0]), den = pa[1] * pb[1]; return { q: `The probability that A solves a problem is ${pa[0]}/${pa[1]} and that B solves it is ${pb[0]}/${pb[1]}. If both try independently, what is the probability the problem is solved?`, a: frac(num, den), d: [frac(pa[0] * pb[0], den), frac(den - num, den), frac(pa[0] * pb[1] + pb[0] * pa[1], den * 2), '1/2'], e: `P(solved) = 1 - P(neither) = 1 - (${pa[1] - pa[0]}/${pa[1]})(${pb[1] - pb[0]}/${pb[1]}) = ${frac(num, den)}.` }; },
    (r) => { const n = pick(r, [3, 4, 5]); const atLeast = 2 ** n - 1; return { q: `${n} coins are tossed. What is the probability of getting at least one head?`, a: frac(atLeast, 2 ** n), d: [frac(1, 2 ** n), frac(n, 2 ** n), '1/2', frac(atLeast - 1, 2 ** n)], e: `P(at least one head) = 1 - P(all tails) = 1 - 1/${2 ** n} = ${frac(atLeast, 2 ** n)}.` }; },
  ],
};

const WORDS = [['APPLE', { P: 2 }], ['BANANA', { A: 3, N: 2 }], ['LETTER', { E: 2, T: 2 }], ['SUCCESS', { S: 3, C: 2 }], ['ORANGE', {}], ['MOTHER', {}], ['COMPUTER', {}], ['BALLOON', { L: 2, O: 2 }], ['ENGINEER', { E: 3, N: 2 }], ['GARDEN', {}], ['PEPPER', { P: 3, E: 2 }], ['COLLEGE', { L: 2, E: 2 }], ['DELHI', {}], ['SCHOOL', { O: 2 }], ['ARRANGE', { A: 2, R: 2 }]];
G['permutations-and-combinations'] = {
  easy: [
    (r) => { const n = int(r, 5, 10), k = int(r, 2, 3); const p = fact(n) / fact(n - k); return { q: `Find the value of ${n}P${k}.`, a: p, d: [nCr(n, k), p * 2, p - n, fact(n) / fact(k)].map(fmtNum), e: `nPr = n!/(n - r)! = ${n}!/${n - k}! = ${p}.` }; },
    (r) => { const n = int(r, 5, 12), k = int(r, 2, 4); const c = nCr(n, k); return { q: `Find the value of ${n}C${k}.`, a: c, d: [fact(n) / fact(n - k), c + n, c * 2, nCr(n, k + 1)].map(fmtNum), e: `nCr = n!/(r!(n - r)!) = ${c}.` }; },
    (r) => { const n = int(r, 3, 7); return { q: `In how many ways can ${n} different books be arranged on a shelf?`, a: fact(n), d: [fact(n - 1), n * n, fact(n) / 2, fact(n + 1)].map(String), e: `${n} distinct objects can be arranged in ${n}! = ${fact(n)} ways.` }; },
  ],
  medium: [
    (r) => { const [w, rep] = pick(r, WORDS); let den = 1; Object.values(rep).forEach((v) => { den *= fact(v); }); const a = fact(w.length) / den; return { q: `In how many different ways can the letters of the word "${w}" be arranged?`, a, d: [fact(w.length), a * 2, a / 2, fact(w.length - 1)].map(fmtNum), e: `${w.length} letters${Object.keys(rep).length ? ` with repeats ${Object.entries(rep).map(([k, v]) => `${k}×${v}`).join(', ')}` : ''}: ${w.length}!${Object.values(rep).map((v) => `/${v}!`).join('')} = ${a}.` }; },
    (r) => { const m = int(r, 4, 8), wmn = int(r, 3, 6), cm = int(r, 1, 3), cw = int(r, 1, 3); const a = nCr(m, cm) * nCr(wmn, cw); return { q: `From ${m} men and ${wmn} women, a committee of ${cm} men and ${cw} women is to be formed. In how many ways can this be done?`, a, d: [nCr(m + wmn, cm + cw), nCr(m, cm) + nCr(wmn, cw), a * 2, a - m].map(String), e: `C(${m},${cm}) × C(${wmn},${cw}) = ${nCr(m, cm)} × ${nCr(wmn, cw)} = ${a}.` }; },
    (r) => { const n = int(r, 4, 9); return { q: `In how many ways can ${n} people be seated around a circular table?`, a: fact(n - 1), d: [fact(n), fact(n - 1) / 2, fact(n - 2), n * (n - 1)].map(String), e: `Circular arrangements of n distinct people = (n - 1)! = ${n - 1}! = ${fact(n - 1)}.` }; },
  ],
  hard: [
    (r) => { const m = int(r, 4, 7), wmn = int(r, 3, 5), k = int(r, 3, 4); const all = nCr(m + wmn, k), none = nCr(m, k); return { q: `A committee of ${k} is to be chosen from ${m} men and ${wmn} women so that it has at least one woman. How many ways?`, a: all - none, d: [all, wmn * nCr(m + wmn - 1, k - 1), all - none + m, nCr(wmn, 1) * nCr(m, k - 1)].map(String), e: `Total C(${m + wmn},${k}) = ${all}; with no woman C(${m},${k}) = ${none}. At least one woman = ${all - none}.` }; },
    (r) => { const w = pick(r, ['LEADER', 'ORANGE', 'GARDEN', 'MOTHER', 'DANGER', 'POLITE', 'CORNEA']); const vowels = [...w].filter((c) => 'AEIOU'.includes(c)); const cons = w.length - vowels.length; const vRep = vowels.length !== new Set(vowels).size ? fact(vowels.length) / 2 : fact(vowels.length); const all = [...w]; const rep = all.length !== new Set(all).size; const a = (fact(cons + 1) * vRep) / (rep && vowels.length === new Set(vowels).size ? 2 : 1); return { q: `In how many ways can the letters of "${w}" be arranged so that the vowels always come together?`, a, d: [fact(w.length), a * 2, fact(cons + 1), Math.round(a / 2)].map(String), e: `Treat the ${vowels.length} vowels (${vowels.join(', ')}) as one block: ${cons + 1} units → ${cons + 1}! ways; vowels inside the block → ${vRep} ways${rep ? ' (dividing for repeated letters)' : ''}. Total = ${a}.` }; },
    (r) => { const n = int(r, 6, 12); const d = (n * (n - 3)) / 2; return { q: `How many diagonals does a polygon with ${n} sides have?`, a: d, d: [nCr(n, 2), d + n, n * (n - 2), d - 1].map(String), e: `Diagonals = C(n,2) - n = n(n - 3)/2 = ${n}×${n - 3}/2 = ${d}.` }; },
  ],
};

G['ages'] = {
  easy: [
    (r) => { const b = int(r, 8, 30), d = int(r, 2, 10); const s = 2 * b + d; return { q: `A is ${d} years older than B. The sum of their ages is ${s}. How old is B?`, a: `${b} years`, d: [`${b + d} years`, `${s / 2} years`, `${b - 2} years`, `${b + 3} years`], e: `B + (B + ${d}) = ${s} → B = ${b}.` }; },
    (r) => { const x = int(r, 5, 20), n = int(r, 3, 10); return { q: `After ${n} years, Ravi will be ${x + n} years old. How old was he ${n} years ago?`, a: `${x - n} years`, d: [`${x} years`, `${x + n} years`, `${x - n + 2} years`, `${x - 2 * n + 1} years`], e: `Present age = ${x + n} - ${n} = ${x}. ${n} years ago = ${x - n}.` }; },
  ],
  medium: [
    (r) => { const a = int(r, 2, 7), b = int(r, 2, 7); if (a === b || gcd(a, b) !== 1) return null; const k = int(r, 3, 8), n = int(r, 2, 10); const A = a * k, B = b * k; const g = gcd(A + n, B + n); return { q: `The present ages of P and Q are in the ratio ${a}:${b}. After ${n} years the ratio will be ${(A + n) / g}:${(B + n) / g}. What is P's present age?`, a: `${A} years`, d: [`${B} years`, `${A + n} years`, `${A + k} years`, `${Math.abs(A - k)} years`], e: `Let ages be ${a}x and ${b}x. (${a}x + ${n})/(${b}x + ${n}) = ${(A + n) / g}/${(B + n) / g} → x = ${k}. P = ${A}.` }; },
    (r) => { const s = int(r, 6, 15), k = pick(r, [3, 4, 5]); const f = k * s; return { q: `A father is ${k} times as old as his son. The sum of their ages is ${f + s}. How old is the father?`, a: `${f} years`, d: [`${s} years`, `${f + s} years`, `${f - 4} years`, `${f + 5} years`], e: `Son = x, father = ${k}x → ${k + 1}x = ${f + s} → x = ${s}. Father = ${f}.` }; },
  ],
  hard: [
    (r) => { const s = int(r, 8, 16), t = int(r, 3, 6), k = pick(r, [3, 4, 5]); const sThen = s - t; const fThen = k * sThen; const f = fThen + t; return { q: `${t} years ago a father was ${k} times as old as his son. Now the sum of their ages is ${f + s}. Find the son's present age.`, a: `${s} years`, d: [`${s + t} years`, `${sThen} years`, `${s + 2} years`, `${f} years`], e: `Let son's age ${t} years ago = x, father's = ${k}x. Now: (x + ${t}) + (${k}x + ${t}) = ${f + s} → x = ${sThen}. Son now = ${s}.` }; },
    (r) => { const a = int(r, 20, 40), b = int(r, 5, 15), n = int(r, 3, 10); const k = (a + n) / (b + n); if (!Number.isInteger(k)) return null; return { q: `Mother is ${a} and daughter is ${b} years old. After how many years will the mother be exactly ${k} times as old as the daughter?`, a: `${n} years`, d: [`${n + 2} years`, `${Math.max(1, n - 2)} years`, `${n * 2} years`, `${a - b} years`], e: `(${a} + x) = ${k}(${b} + x) → x = (${a} - ${k * b})/${k - 1} = ${n}.` }; },
  ],
};

G['partnership'] = {
  easy: [
    (r) => { const a = int(r, 2, 9) * 1000, b = int(r, 2, 9) * 1000; if (a === b) return null; const P = int(r, 2, 20) * ((a + b) / gcd(a, b)) * 10; const sh = (P * a) / (a + b); return { q: `A invests ${money(a)} and B invests ${money(b)} in a business for the same period. Out of a profit of ${money(P)}, what is A's share?`, a: money(sh), d: [money(P - sh), money(P / 2), money(sh + 100), money(Math.round((P * b) / a))], e: `Ratio = ${a}:${b}. A's share = ${a}/${a + b} × ${P} = ${money(sh)}.` }; },
  ],
  medium: [
    (r) => { const a = int(r, 2, 9) * 1000, b = int(r, 2, 9) * 1000, ta = int(r, 4, 12), tb = int(r, 4, 12); const A = a * ta, B = b * tb; const g = gcd(A, B); const P = ((A + B) / g) * int(r, 50, 400); const sh = (P * B) / (A + B); return { q: `A invests ${money(a)} for ${ta} months and B invests ${money(b)} for ${tb} months. Out of a total profit of ${money(P)}, what is B's share?`, a: money(sh), d: [money(P - sh), money((P * b) / (a + b)), money(P / 2), money(sh + 500)], e: `Capital × time: A = ${A}, B = ${B} → ratio ${A / g}:${B / g}. B gets ${money(sh)}.` }; },
  ],
  hard: [
    (r) => { const a = int(r, 3, 9) * 1000, b = int(r, 3, 9) * 1000, join = int(r, 2, 8); const A = a * 12, B = b * (12 - join); const g = gcd(A, B); const P = ((A + B) / g) * int(r, 40, 300); const sh = (P * A) / (A + B); return { q: `A starts a business with ${money(a)}. After ${join} months, B joins with ${money(b)}. At the end of the year the profit is ${money(P)}. What is A's share?`, a: money(sh), d: [money(P - sh), money((P * a) / (a + b)), money(P / 2), money(sh - 300)], e: `A: ${a}×12 = ${A}; B: ${b}×${12 - join} = ${B}. Ratio ${A / g}:${B / g}. A = ${money(sh)}.` }; },
    (r) => { const a = int(r, 3, 9) * 1000, b = int(r, 3, 9) * 1000, wd = int(r, 3, 8), w = int(r, 1, 2) * 1000; if (w >= a) return null; const A = a * wd + (a - w) * (12 - wd), B = b * 12; const g = gcd(A, B); return { q: `A and B start a business with ${money(a)} and ${money(b)}. After ${wd} months, A withdraws ${money(w)}. In what ratio should the annual profit be shared?`, a: `${A / g}:${B / g}`, d: [`${a / gcd(a, b)}:${b / gcd(a, b)}`, `${B / g}:${A / g}`, `${(A + 1000) / gcd(A + 1000, B)}:${B / gcd(A + 1000, B)}`, '1:1'], e: `A: ${a}×${wd} + ${a - w}×${12 - wd} = ${A}; B: ${b}×12 = ${B}. Ratio = ${A / g}:${B / g}.` }; },
  ],
};

G['mensuration'] = {
  easy: [
    (r) => { const l = int(r, 5, 40), b = int(r, 3, 30); return { q: `Find the area of a rectangle with length ${l} m and breadth ${b} m.`, a: `${l * b} m²`, d: [`${2 * (l + b)} m²`, `${l * b + l} m²`, `${(l * b) / 2} m²`, `${l + b} m²`], e: `Area = l × b = ${l} × ${b} = ${l * b} m².` }; },
    (r) => { const rr = 7 * int(r, 1, 6); return { q: `Find the circumference of a circle of radius ${rr} cm. (Use π = 22/7)`, a: `${(2 * 22 * rr) / 7} cm`, d: [`${(22 * rr * rr) / 7} cm`, `${(22 * rr) / 7} cm`, `${(2 * 22 * rr) / 7 + 7} cm`, `${4 * rr} cm`], e: `C = 2πr = 2 × 22/7 × ${rr} = ${(2 * 22 * rr) / 7} cm.` }; },
    (r) => { const s = int(r, 3, 25); return { q: `What is the area of a square with perimeter ${4 * s} cm?`, a: `${s * s} cm²`, d: [`${16 * s} cm²`, `${s * s + s} cm²`, `${4 * s} cm²`, `${(s * s) / 2} cm²`], e: `Side = ${4 * s}/4 = ${s}. Area = ${s * s} cm².` }; },
  ],
  medium: [
    (r) => { const rr = 7 * int(r, 1, 3), h = int(r, 2, 20); const v = (22 * rr * rr * h) / 7; return { q: `Find the volume of a cylinder with radius ${rr} cm and height ${h} cm. (π = 22/7)`, a: `${v} cm³`, d: [`${v / 3} cm³`, `${(2 * 22 * rr * h) / 7} cm³`, `${v * 2} cm³`, `${v + 154} cm³`], e: `V = πr²h = 22/7 × ${rr}² × ${h} = ${v} cm³.` }; },
    (r) => { const rr = 7 * int(r, 1, 3), h = 3 * int(r, 2, 10); const v = (22 * rr * rr * h) / 21; return { q: `Find the volume of a cone with radius ${rr} cm and height ${h} cm. (π = 22/7)`, a: `${fmtNum(v)} cm³`, d: [`${fmtNum(v * 3)} cm³`, `${fmtNum(v / 2)} cm³`, `${fmtNum(v + 22)} cm³`, `${fmtNum(v * 2)} cm³`], e: `V = (1/3)πr²h = ${fmtNum(v)} cm³.` }; },
    (r) => { const a = int(r, 2, 15); return { q: `What is the total surface area of a cube with edge ${a} cm?`, a: `${6 * a * a} cm²`, d: [`${a ** 3} cm²`, `${4 * a * a} cm²`, `${12 * a} cm²`, `${6 * a * a + a} cm²`], e: `TSA = 6a² = 6 × ${a}² = ${6 * a * a} cm².` }; },
  ],
  hard: [
    (r) => { const p = pick(r, [10, 20, 25, 50]); const c = round2((1 + p / 100) ** 2 * 100 - 100); return { q: `If each side of a square is increased by ${p}%, by what percent does its area increase?`, a: `${fmtNum(c)}%`, d: [`${2 * p}%`, `${p}%`, `${fmtNum(round2(c + 5))}%`, `${fmtNum(round2((p * p) / 100))}%`], e: `New area = (1 + ${p / 100})² = ${fmtNum(round2((1 + p / 100) ** 2))} × old → increase ${fmtNum(c)}% (= 2p + p²/100).` }; },
    (r) => { const p = pick(r, [10, 20, 25]), q = pick(r, [10, 20]); const c = round2((1 + p / 100) * (1 - q / 100) * 100 - 100); return { q: `The length of a rectangle is increased by ${p}% and its breadth is decreased by ${q}%. What is the percentage change in its area?`, a: c >= 0 ? `${fmtNum(c)}% increase` : `${fmtNum(-c)}% decrease`, d: [`${Math.abs(p - q) || 2}% increase`, `${fmtNum(Math.abs(c) + 2)}% decrease`, `No change`, `${fmtNum(Math.abs(c) + 1)}% increase`], e: `Net = ${p} - ${q} - ${p}×${q}/100 = ${fmtNum(c)}%.` }; },
    (r) => { const rr = 7 * int(r, 1, 3); const sa = (4 * 22 * rr * rr) / 7; return { q: `Find the surface area of a sphere of radius ${rr} cm. (π = 22/7)`, a: `${sa} cm²`, d: [`${sa / 2} cm²`, `${(4 * 22 * rr ** 3) / 21} cm²`, `${sa * 2} cm²`, `${sa - 44} cm²`], e: `Surface area = 4πr² = 4 × 22/7 × ${rr}² = ${sa} cm².` }; },
  ],
};

// Data interpretation: each question carries its own small table.
G['data-interpretation'] = (() => {
  const products = ['Laptops', 'Phones', 'Tablets', 'Watches', 'Cameras'];
  const table = (r) => {
    const rows = products.map((p) => [p, int(r, 4, 30) * 10, int(r, 4, 30) * 10]);
    const txt = `Sales (units) of a store — ${rows.map(([p, a, b]) => `${p}: 2023 = ${a}, 2024 = ${b}`).join('; ')}.`;
    return { rows, txt };
  };
  return {
    easy: [
      (r) => { const { rows, txt } = table(r); const tot = rows.reduce((s, x) => s + x[2], 0); return { q: `${txt} What were the total sales in 2024?`, a: tot, d: near(r, tot), e: `Add the 2024 column: ${rows.map((x) => x[2]).join(' + ')} = ${tot}.` }; },
      (r) => { const { rows, txt } = table(r); const best = [...rows].sort((a, b) => b[1] - a[1]); if (best[0][1] === best[1][1]) return null; return { q: `${txt} Which product had the highest sales in 2023?`, a: best[0][0], d: products.filter((p) => p !== best[0][0]), e: `Compare the 2023 values; ${best[0][0]} is highest with ${best[0][1]}.` }; },
    ],
    medium: [
      (r) => { const { rows, txt } = table(r); const x = pick(r, rows); const ch = round2(((x[2] - x[1]) / x[1]) * 100); return { q: `${txt} What is the percentage change in sales of ${x[0]} from 2023 to 2024?`, a: `${fmtNum(ch)}%`, d: [`${fmtNum(round2(ch + 10))}%`, `${fmtNum(round2(((x[2] - x[1]) / x[2]) * 100))}%`, `${fmtNum(round2(-ch))}%`, `${fmtNum(round2(ch / 2))}%`], e: `(${x[2]} - ${x[1]})/${x[1]} × 100 = ${fmtNum(ch)}%.` }; },
      (r) => { const { rows, txt } = table(r); const avg = round2(rows.reduce((s, x) => s + x[1], 0) / rows.length); return { q: `${txt} What is the average sales per product in 2023?`, a: fmtNum(avg), d: near(r, avg), e: `Sum of 2023 = ${rows.reduce((s, x) => s + x[1], 0)}; average = /5 = ${fmtNum(avg)}.` }; },
    ],
    hard: [
      (r) => { const { rows, txt } = table(r); const a = pick(r, rows), b = pick(r, rows); if (a[0] === b[0]) return null; const g = gcd(a[1] + a[2], b[1] + b[2]); return { q: `${txt} What is the ratio of total sales (both years) of ${a[0]} to ${b[0]}?`, a: `${(a[1] + a[2]) / g}:${(b[1] + b[2]) / g}`, d: [`${(b[1] + b[2]) / g}:${(a[1] + a[2]) / g}`, `${a[1] / gcd(a[1], b[1])}:${b[1] / gcd(a[1], b[1])}`, `${a[2] / gcd(a[2], b[2])}:${b[2] / gcd(a[2], b[2])}`, '1:1'], e: `${a[0]}: ${a[1] + a[2]}, ${b[0]}: ${b[1] + b[2]}. Ratio = ${(a[1] + a[2]) / g}:${(b[1] + b[2]) / g}.` }; },
      (r) => { const { rows, txt } = table(r); const t23 = rows.reduce((s, x) => s + x[1], 0); const x = pick(r, rows); const share = round2((x[1] / t23) * 100); return { q: `${txt} What percentage of the total 2023 sales came from ${x[0]}?`, a: `${fmtNum(share)}%`, d: [`${fmtNum(round2(share + 5))}%`, `${fmtNum(round2(share - 3))}%`, '20%', `${fmtNum(round2((x[2] / t23) * 100))}%`], e: `${x[1]}/${t23} × 100 = ${fmtNum(share)}%.` }; },
      (r) => { const { rows, txt } = table(r); const inc = rows.filter((x) => x[2] > x[1]).length; return { q: `${txt} For how many products did sales increase from 2023 to 2024?`, a: inc, d: ['0', '1', '2', '3', '4', '5'], e: `Compare each pair; ${inc} product(s) increased.` }; },
    ],
  };
})();

// ---------------------------------------------------------------- lessons
const L = {
  'number-systems': { title: 'Number Systems', explanation: 'Number systems questions test divisibility, remainders, unit digits and factors. Natural numbers start at 1, whole numbers at 0. Integers include negatives. A prime has exactly two factors.', formulas: ['Sum of first n natural numbers = n(n+1)/2', 'Sum of first n odd numbers = n²', 'Sum of squares = n(n+1)(2n+1)/6', 'If N = p^a × q^b × r^c, number of factors = (a+1)(b+1)(c+1)', 'Dividend = Divisor × Quotient + Remainder'], shortcuts: ['Divisible by 3/9: digit sum divisible by 3/9', 'Divisible by 4: last two digits divisible by 4; by 8: last three digits', 'Divisible by 11: difference of alternate digit sums is 0 or a multiple of 11', 'Unit digits of powers repeat every 4: find n mod 4', 'Highest power of p in n! = floor(n/p) + floor(n/p²) + ...'], examples: [['Find the unit digit of 7^95.', 'Cycle of 7: 7, 9, 3, 1 (length 4). 95 mod 4 = 3 → third term = 3.'], ['How many factors does 360 have?', '360 = 2³ × 3² × 5¹ → (3+1)(2+1)(1+1) = 24 factors.']] },
  'hcf-and-lcm': { title: 'HCF and LCM', explanation: 'HCF (Highest Common Factor) is the largest number dividing all given numbers; LCM (Least Common Multiple) is the smallest number divisible by all of them. Use prime factorisation or the division method.', formulas: ['HCF × LCM = product of two numbers', 'HCF of fractions = HCF of numerators / LCM of denominators', 'LCM of fractions = LCM of numerators / HCF of denominators'], shortcuts: ['Bells/lights together again → LCM', 'Largest tile, largest container, greatest divisor → HCF', 'Least number leaving the same remainder r → LCM + r', 'Greatest number leaving remainders r1, r2 → HCF(a - r1, b - r2)'], examples: [['Find the least number which when divided by 12, 15 and 20 leaves remainder 5.', 'LCM(12, 15, 20) = 60. Answer = 60 + 5 = 65.'], ['Product of two numbers is 2160 and HCF is 12. Find LCM.', 'LCM = 2160/12 = 180.']] },
  'percentages': { title: 'Percentages', explanation: 'Percent means "per hundred". Percentages compare quantities and describe increase or decrease.', formulas: ['x% of y = xy/100', '% change = (new - old)/old × 100', 'Successive changes a% and b%: a + b + ab/100', 'If price rises by r%, cut consumption by r/(100 + r) × 100% to keep expenditure same'], shortcuts: ['Memorise fractions: 1/8 = 12.5%, 1/6 = 16.67%, 1/3 = 33.33%, 1/12 = 8.33%', 'If A is r% more than B, B is r/(100 + r) × 100% less than A', '+x% then -x% always gives a net loss of x²/100 %'], examples: [['A salary is raised 20% then cut 20%. Net change?', '20 - 20 - 400/100 = -4% → 4% decrease.'], ['Price rises 25%. Reduce consumption by?', '25/125 × 100 = 20%.']] },
  'profit-and-loss': { title: 'Profit and Loss', explanation: 'Cost Price (CP) is what you pay; Selling Price (SP) is what you receive. Marked Price (MP) is the tagged price before discount. Profit/loss % is always on CP; discount % is always on MP.', formulas: ['Profit% = (SP - CP)/CP × 100', 'SP = CP × (100 + gain%)/100', 'SP = MP × (100 - discount%)/100', 'False weight gain% = error/(true value - error) × 100'], shortcuts: ['Same SP, x% gain on one and x% loss on other → loss of x²/100 %', 'CP of x articles = SP of y articles → gain% = (x - y)/y × 100', 'Successive discounts a% and b% = a + b - ab/100'], examples: [['MP is 40% above CP, discount 10%. Profit%?', 'CP 100 → MP 140 → SP 126 → profit 26%.'], ['A dealer uses 900 g for 1 kg. Gain%?', '100/900 × 100 = 11.11%.']] },
  'simple-interest': { title: 'Simple Interest', explanation: 'Simple interest is calculated only on the original principal every year.', formulas: ['SI = P × R × T/100', 'Amount = P + SI', 'R = SI × 100/(P × T)', 'Sum doubles in T years → R = 100/T'], shortcuts: ['If a sum becomes k times in t years, it becomes m times in t(m - 1)/(k - 1) years', 'SI for each year is the same, so interest grows linearly'], examples: [['At what rate does a sum double in 8 years (SI)?', 'R = 100/8 = 12.5%.'], ['SI on ₹5000 at 8% for 3 years?', '5000 × 8 × 3/100 = ₹1200.']] },
  'compound-interest': { title: 'Compound Interest', explanation: 'In compound interest, interest is added to the principal and the next interest is calculated on the new amount.', formulas: ['A = P(1 + R/100)^n', 'CI = A - P', 'Half-yearly: rate R/2, periods 2n', 'CI - SI (2 years) = P(R/100)²', 'CI - SI (3 years) = P(R/100)²(3 + R/100)'], shortcuts: ['10% for 2 years ⇒ multiply by 1.21; 3 years ⇒ 1.331', 'If a sum doubles in n years, it becomes 2^k times in kn years', 'Effective rate for 2 years at r% = 2r + r²/100'], examples: [['CI on ₹10000 at 10% for 2 years?', '10000 × 1.21 - 10000 = ₹2100.'], ['CI - SI for 2 years at 5% on ₹8000?', '8000 × (0.05)² = ₹20.']] },
  'ratio-and-proportion': { title: 'Ratio and Proportion', explanation: 'A ratio compares two quantities of the same kind. A proportion states that two ratios are equal (a:b = c:d).', formulas: ['a:b = c:d ⇒ ad = bc', 'Fourth proportional of a, b, c = bc/a', 'Mean proportional of a and b = √(ab)', 'Third proportional of a and b = b²/a', 'A:B = a:b and B:C = c:d ⇒ A:B:C = ac:bc:bd'], shortcuts: ['Write unknown quantities as ax and bx', 'For dividing amounts, share = part/total × amount'], examples: [['Divide ₹1200 in the ratio 3:5.', '1200/8 = 150 → ₹450 and ₹750.'], ['Mean proportional of 9 and 16?', '√144 = 12.']] },
  'averages': { title: 'Averages', explanation: 'Average = sum of observations / number of observations. Questions often add or remove items and ask how the average changes.', formulas: ['Average = Sum/n', 'Average of first n natural numbers = (n + 1)/2', 'New member\'s value = new avg + n × change (when the group grows from n to n+1)', 'Combined average = (n1a1 + n2a2)/(n1 + n2)'], shortcuts: ['Average of consecutive numbers = (first + last)/2', 'If each value increases by k, the average increases by k', 'Batsman: new average = score - (innings - 1) × increase'], examples: [['Average of 30 students is 14. With the teacher, average is 15. Teacher\'s age?', '15 × 31 - 14 × 30 = 465 - 420 = 45.']] },
  'mixtures': { title: 'Mixtures and Alligation', explanation: 'Alligation finds the ratio in which two ingredients at different prices/concentrations must be mixed to get a desired mean value.', formulas: ['Cheaper : Dearer = (d - m) : (m - c)', 'Repeated replacement: final = initial × (1 - x/V)^n'], shortcuts: ['Draw the alligation cross with c and d on top, m in the middle', 'Quantity that does not change (e.g. milk when adding water) is the anchor'], examples: [['Mix rice at ₹40 and ₹60 to get ₹46. Ratio?', '(60 - 46):(46 - 40) = 14:6 = 7:3.']] },
  'time-and-work': { title: 'Time and Work', explanation: 'Work questions use rates. If A finishes work in a days, A does 1/a of the work per day. Rates add when people work together.', formulas: ['Together: 1/a + 1/b ⇒ time = ab/(a + b)', 'M1 × D1 × H1 = M2 × D2 × H2 (for the same work)', 'B alone = at/(a - t) when A alone = a and together = t'], shortcuts: ['LCM method: take total work = LCM of days; each person\'s efficiency = work/days', 'Efficiency is inversely proportional to time'], examples: [['A: 12 days, B: 24 days. Together?', '12×24/36 = 8 days.']] },
  'pipes-and-cisterns': { title: 'Pipes and Cisterns', explanation: 'Identical to time and work: inlet pipes do positive work, outlet pipes or leaks do negative work.', formulas: ['Fill in a hours, empty in b hours (b > a): net time = ab/(b - a)', 'Two inlets: ab/(a + b)'], shortcuts: ['Use LCM of all times as tank capacity in units', 'Subtract the rate of leaks/outlets'], examples: [['Pipe fills in 6 h, leak empties in 12 h. Time?', '6×12/(12 - 6) = 12 hours.']] },
  'time-speed-distance': { title: 'Time, Speed and Distance', explanation: 'Distance = Speed × Time. Use relative speed when two objects move towards or away from each other.', formulas: ['km/h → m/s: × 5/18; m/s → km/h: × 18/5', 'Average speed (equal distances) = 2xy/(x + y)', 'Opposite direction relative speed = a + b; same direction = a - b'], shortcuts: ['If speed ratio is a:b, time ratio is b:a for the same distance', 'Late/early problems: difference in time × product of speeds/difference of speeds = distance'], examples: [['Average speed at 40 and 60 km/h for equal distances?', '2×40×60/100 = 48 km/h.']] },
  'trains': { title: 'Problems on Trains', explanation: 'A train crossing a pole/person covers its own length; crossing a platform/bridge/another train covers the sum of lengths.', formulas: ['Time = (L1 + L2)/relative speed', 'Pole: time = length/speed'], shortcuts: ['Convert km/h to m/s first: 36 → 10, 54 → 15, 72 → 20, 90 → 25, 108 → 30'], examples: [['200 m train at 72 km/h crosses a 300 m platform. Time?', '500/20 = 25 s.']] },
  'boats-and-streams': { title: 'Boats and Streams', explanation: 'Downstream the stream helps the boat; upstream the stream opposes it.', formulas: ['Downstream = b + s; Upstream = b - s', 'b = (D + U)/2; s = (D - U)/2'], shortcuts: ['If upstream takes k times as long, b = s(k + 1)/(k - 1)'], examples: [['Down 14 km/h, up 8 km/h. Boat & stream speed?', 'b = 11, s = 3 km/h.']] },
  'probability': { title: 'Probability', explanation: 'Probability = favourable outcomes / total equally likely outcomes. It always lies between 0 and 1.', formulas: ['P(not A) = 1 - P(A)', 'P(A or B) = P(A) + P(B) - P(A and B)', 'Independent events: P(A and B) = P(A) × P(B)', 'At least one = 1 - P(none)'], shortcuts: ['Two dice → 36 outcomes; sum 7 has the most (6) ways', 'Deck: 52 cards, 4 suits, 12 face cards, 26 red'], examples: [['Two dice: P(sum = 8)?', '(2,6),(3,5),(4,4),(5,3),(6,2) → 5/36.']] },
  'permutations-and-combinations': { title: 'Permutations and Combinations', explanation: 'Permutation = arrangement (order matters). Combination = selection (order does not matter).', formulas: ['nPr = n!/(n - r)!', 'nCr = n!/(r!(n - r)!)', 'Arrangements with repeats = n!/(p! q! ...)', 'Circular arrangements = (n - 1)!', 'Diagonals of n-gon = n(n - 3)/2'], shortcuts: ['"Together" → treat as one block; multiply by internal arrangements', '"At least one" → total - none', 'nCr = nC(n - r)'], examples: [['Arrangements of BANANA?', '6!/(3! 2!) = 60.']] },
  'ages': { title: 'Problems on Ages', explanation: 'Translate statements into equations. The age difference between two people never changes.', formulas: ['If present age is x, after n years = x + n, n years ago = x - n'], shortcuts: ['Use ratio multipliers (ax, bx)', 'Check answers by substituting back — fastest in MCQs'], examples: [['Ratio 3:5 now, 5:7 after 6 years. Ages?', '(3x+6)/(5x+6) = 5/7 → x = 6 → 18 and 30.']] },
  'partnership': { title: 'Partnership', explanation: 'Profit is shared in the ratio of capital × time invested by each partner.', formulas: ['Share ratio = C1T1 : C2T2 : ...'], shortcuts: ['Same time period → ratio of capitals only', 'Late joiner invests for (12 - months late) months'], examples: [['A ₹5000 for 12 m, B ₹6000 for 10 m. Ratio?', '60000:60000 = 1:1.']] },
  'mensuration': { title: 'Mensuration', explanation: 'Mensuration covers perimeter, area, surface area and volume of 2D and 3D shapes.', formulas: ['Rectangle area = lb; perimeter = 2(l + b)', 'Circle area = πr²; circumference = 2πr', 'Cylinder volume = πr²h; CSA = 2πrh', 'Cone volume = (1/3)πr²h', 'Sphere volume = (4/3)πr³; surface = 4πr²', 'Cube: volume a³, TSA 6a²'], shortcuts: ['% change in area when both sides change by x% = 2x + x²/100', 'Use radius in multiples of 7 with π = 22/7'], examples: [['Cylinder r = 7, h = 10. Volume?', '22/7 × 49 × 10 = 1540 cm³.']] },
  'data-interpretation': { title: 'Data Interpretation', explanation: 'DI presents data in tables, bar charts, pie charts or line graphs and asks calculation questions. Speed and approximation matter.', formulas: ['% change = (new - old)/old × 100', 'Share % = part/total × 100', 'Average = total/count'], shortcuts: ['Read the question first, then only the data you need', 'Approximate when options are far apart', 'Watch units (thousands, lakhs, %)'], examples: [['Sales 120 → 150. % increase?', '30/120 × 100 = 25%.']] },
};

const TOPIC_ORDER = Object.keys(L);

function build() {
  const questions = [];
  TOPIC_ORDER.forEach((slug, i) => {
    questions.push(...generateTopic('quant', slug, G[slug], 18, 100 + i));
  });
  const topics = TOPIC_ORDER.map((slug, i) => ({
    slug, title: L[slug].title, summary: L[slug].explanation.split('.')[0] + '.', sort: i,
    lesson: {
      title: L[slug].title, difficulty: 'easy', minutes: 25,
      content: {
        explanation: L[slug].explanation, formulas: L[slug].formulas, shortcuts: L[slug].shortcuts,
        solved_examples: L[slug].examples.map(([q, s]) => ({ question: q, solution: s })),
        practice_note: 'Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button.',
      },
    },
  }));
  return { topics, questions };
}

module.exports = { build };
